"""Provider registry and factory for PaperBanana."""

from __future__ import annotations

import structlog

from paperbanana.core.config import Settings
from paperbanana.providers.base import ImageGenProvider, VLMProvider

logger = structlog.get_logger()


class ProviderRegistry:
    """Factory for creating VLM and image generation providers from config."""

    @staticmethod
    def create_vlm(settings: Settings) -> VLMProvider:
        """Create a VLM provider based on settings."""
        provider = settings.vlm_provider.lower()
        logger.info("Creating VLM provider", provider=provider, model=settings.vlm_model)

        if provider == "gemini":
            from paperbanana.providers.vlm.gemini import GeminiVLM

            return GeminiVLM(
                api_key=[REDACTED],
                model=settings.vlm_model,
            )
        elif provider == "openrouter":
            from paperbanana.providers.vlm.openrouter import OpenRouterVLM

            return OpenRouterVLM(
                api_key=[REDACTED],
                model=settings.vlm_model,
            )
        else:
            raise ValueError(f"Unknown VLM provider: {provider}. Available: gemini, openrouter")

    @staticmethod
    def create_image_gen(settings: Settings) -> ImageGenProvider:
        """Create an image generation provider based on settings."""
        provider = settings.image_provider.lower()
        logger.info("Creating image gen provider", provider=provider, model=settings.image_model)

        if provider == "google_imagen":
            from paperbanana.providers.image_gen.google_imagen import GoogleImagenGen

            return GoogleImagenGen(
                api_key=[REDACTED],
                model=settings.image_model,
            )
        elif provider == "openrouter_imagen":
            from paperbanana.providers.image_gen.openrouter_imagen import OpenRouterImageGen

            return OpenRouterImageGen(
                api_key=[REDACTED],
                model=settings.image_model,
            )
        else:
            raise ValueError(
                f"Unknown image provider: {provider}. Available: google_imagen, openrouter_imagen"
            )

"""Symmetric encryption for secrets (Admin Tokens, API Keys).

Uses Fernet (AES-128-CBC + HMAC-SHA256) with a key derived from the machine ID.
Goal: prevent plain-text exposure if files are read by the Agent or leaked —
this is NOT a substitute for OS-level access control.
"""

from __future__ import annotations

import base64
import hashlib
import uuid
from pathlib import Path

from cryptography.fernet import Fernet, InvalidToken

# Deterministic salt — changing this invalidates all stored secrets.
_SALT = b"agent-ml-research-tum-v1"


def _derive_key() -> bytes:
    """Derive a Fernet key from the machine's MAC address + salt."""
    machine_id = str(uuid.getnode()).encode()
    raw = hashlib.pbkdf2_hmac("sha256", machine_id, _SALT, iterations=100_000, dklen=32)
    return base64.urlsafe_b64encode(raw)


_fernet: Fernet | None = None


def _get_fernet() -> Fernet:
    global _fernet
    if _fernet is None:
        _fernet = Fernet(_derive_key())
    return _fernet


def encrypt(plaintext: str) -> str:
    """Encrypt a string, return URL-safe base64 ciphertext."""
    return _get_fernet().encrypt(plaintext.encode()).decode()


def decrypt(ciphertext: str) -> str | None:
    """Decrypt ciphertext. Returns None if invalid/corrupted."""
    try:
        return _get_fernet().decrypt(ciphertext.encode()).decode()
    except (InvalidToken, Exception):
        return None


# --- File-level helpers (for admin token / API keys) ---

def save_secret(path: Path, plaintext: str) -> None:
    """Encrypt and write a secret to a file."""
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(encrypt(plaintext))


def load_secret(path: Path) -> str | None:
    """Read and decrypt a secret from a file. Returns None if missing/invalid."""
    if not path.exists():
        return None
    ciphertext = path.read_text().strip()
    if not ciphertext:
        return None
    return decrypt(ciphertext)

